  "{reach}: favorites, visibility and order. These preferences follow the provider instance ID, including matching default slots on other machines.":
    "{reach}: избранное, видимость и порядок. Эти настройки привязаны к ID экземпляра провайдера, включая совпадающие слоты по умолчанию на других машинах.",
  "{name} cleared because the server address changed. Enter it again to use it there.":
    "{name} очищен, потому что изменился адрес сервера. Введите его снова, чтобы использовать там.",
  "Uses Cursor’s Agent SDK with a local agent loop and hosted inference. Sign in with your Cursor account or use an API key. SDK access may require a paid Cursor plan; models and usage depend on your account.":
    "Использует Agent SDK от Cursor с локальным циклом агента и облачным выводом. Войдите через аккаунт Cursor или используйте API-ключ. Для доступа к SDK может понадобиться платный план Cursor; модели и лимиты зависят от вашего аккаунта.",
