  "Project trust, account permissions and runtime policy may prevent use. SpecWithCode project grants apply only to SpecWithCode-managed calls.":
    "Доверие к проекту, права аккаунта и политика среды выполнения могут помешать использованию. Разрешения проектов SpecWithCode действуют только для вызовов, которыми управляет SpecWithCode.",
