  "Add an API account": "Добавить API-аккаунт",
  "Turns on this account are billed per token to its credits at API prices, not to your subscription. Create the key in the {console}. Add one account per key; when one runs out of credits, a stopped thread can continue on the next.":
    "Ходы в этом аккаунте оплачиваются за токены из его кредитов по ценам API, а не из вашей подписки. Создайте ключ в {console}. Добавляйте по одному аккаунту на ключ; когда у одного закончатся кредиты, остановленный тред сможет продолжить на следующем.",
  "API key": "API-ключ",
