  "Needed for a key that is not scoped to a workspace (user keys, sk-ant-usr…). Copy it from Settings → Workspaces in the Claude Console.":
    "Нужен для ключа, не привязанного к рабочему пространству (пользовательские ключи, sk-ant-usr…). Скопируйте его в Settings → Workspaces в Claude Console.",
