  "Read Codex account quotas on {environmentLabel}. Claude accounts are skipped. This does not connect chat models or sign in an agent. The key stays on that server.":
    "Читать квоты аккаунтов Codex на {environmentLabel}. Аккаунты Claude пропускаются. Это не подключает модели чата и не выполняет вход агента. Ключ остаётся на том сервере.",
  "Hub URL": "URL хаба",
