    "{name} открыт, поэтому его cookie пока нельзя прочитать. Закройте его и продолжите.",
  "I’ve quit it": "Я закрыл его",
  "Let SpecWithCode read {name}’s cookies": "Разрешите SpecWithCode читать cookie {name}",
