    "Чтобы импортировать cookie из {name}, SpecWithCode нужен полный доступ к диску. Включите его в Системных настройках и вернитесь, чтобы завершить импорт — после импорта доступ можно снова отозвать.",
  "Access is still required. Quit and reopen SpecWithCode if you just allowed it, then retry the import.":
    "Доступ всё ещё нужен. Если вы только что его разрешили, закройте и снова откройте SpecWithCode, затем повторите импорт.",
