  "Enable network access": "Включить сетевой доступ",
  Retry: "Повторить",
  "Switch to Windows": "Переключиться на Windows",
  "WSL backend couldn't start: {preflightError}":
    "Не удалось запустить бэкенд WSL: {preflightError}",
  Off: "Выкл.",
  "Default distro": "Дистрибутив по умолчанию",
  "Run WSL only": "Только WSL",
  "Enable Tailscale HTTPS": "Включить Tailscale HTTPS",
  "More actions for this machine": "Другие действия для этой машины",
  "Up to date": "Актуальная версия",
  "This connection can create access links but cannot view authorized clients.":
    "Это подключение может создавать ссылки доступа, но не может видеть авторизованных клиентов.",
  "Enable network access?": "Включить сетевой доступ?",
  "Disable network access?": "Отключить сетевой доступ?",
  "Let your other devices connect to SpecWithCode over your local network. This mode uses plain HTTP, so its traffic is not encrypted: anyone on the same network can capture the sign-in and use it to control the app. Turn it on only on a network you trust, and use SpecWithCode Connect or Tailscale HTTPS for remote access. Pair devices to give them access. The app will restart.":
    "Позвольте другим своим устройствам подключаться к SpecWithCode по локальной сети. Этот режим использует обычный HTTP, поэтому трафик не шифруется: любой в той же сети может перехватить вход и управлять приложением. Включайте его только в сети, которой доверяете, а для удалённого доступа используйте SpecWithCode Connect или Tailscale HTTPS. Чтобы дать устройствам доступ, свяжите их. Приложение перезапустится.",
  "Devices connected over your local network will disconnect. Existing tunnels, such as SpecWithCode Connect or Tailscale HTTPS, keep working. SpecWithCode will restart.":
    "Устройства, подключённые по локальной сети, отключатся. Существующие туннели, например SpecWithCode Connect или Tailscale HTTPS, продолжат работать. SpecWithCode перезапустится.",
  "Restarting…": "Перезапуск…",
  "Restart and enable": "Перезапустить и включить",
  "Restart and disable": "Перезапустить и отключить",
  "Turn off WSL and switch back to Windows?": "Выключить WSL и вернуться к Windows?",
  "Disable WSL backend?": "Отключить бэкенд WSL?",
  "Switch WSL distro?": "Сменить дистрибутив WSL?",
  "Start the WSL backend": "Запустить бэкенд WSL",
  "Run only the WSL backend?": "Запускать только бэкенд WSL?",
  "Re-enable the Windows backend?": "Снова включить бэкенд Windows?",
  "SpecWithCode will restart on the Windows backend. Threads and projects opened against WSL stay safe inside the distro and become available again when you re-enable WSL.":
    "SpecWithCode перезапустится на бэкенде Windows. Треды и проекты, открытые в WSL, сохранятся внутри дистрибутива и снова станут доступны, когда вы включите WSL.",
  "The WSL backend will stop. Threads and projects opened against WSL stay safe inside the distro, but they'll be unavailable in SpecWithCode until you re-enable WSL.":
    "Бэкенд WSL остановится. Треды и проекты, открытые в WSL, сохранятся внутри дистрибутива, но будут недоступны в SpecWithCode, пока вы снова не включите WSL.",
  "SpecWithCode will restart the WSL backend on the new distro. Sessions still running on the current distro will be interrupted.":
    "SpecWithCode перезапустит бэкенд WSL на новом дистрибутиве. Сессии, ещё работающие на текущем дистрибутиве, будут прерваны.",
  "Run the WSL backend alongside the Windows one, or stop the Windows backend and use only WSL? You can change this later from Settings.":
    "Запускать бэкенд WSL вместе с Windows или остановить бэкенд Windows и использовать только WSL? Это можно изменить позже в настройках.",
  "SpecWithCode will restart and start only the WSL backend. Your Windows-side projects won't be accessible until you turn this off again.":
    "SpecWithCode перезапустится и запустит только бэкенд WSL. Проекты на стороне Windows будут недоступны, пока вы снова это не выключите.",
  "SpecWithCode will restart and bring the Windows backend back up alongside WSL.":
    "SpecWithCode перезапустится и снова запустит бэкенд Windows вместе с WSL.",
