  "Copy from…": "Скопировать из…",
  "No custom options. The composer uses the provider's default options.":
    "Своих параметров нет. Поле ввода использует параметры провайдера по умолчанию.",
  "Custom option": "Свой параметр",
  "Jev, from TypeSafe, picks one option from a fixed list in well under a second and costs almost nothing. When the coordinator does not say whether a task is complex or routine, Jev picks the lane, and it settles the kind of work when the keyword rules are unsure. The coordinator can also ask it any multiple-choice question. If Jev is slow or unreachable, routing keeps the rules' answer.":
    "Jev от TypeSafe выбирает один вариант из фиксированного списка гораздо быстрее секунды и почти ничего не стоит. Когда координатор не говорит, сложная задача или рутинная, Jev выбирает полосу, а также определяет тип работы, когда правила по ключевым словам не уверены. Координатор может задать ему любой вопрос с вариантами ответа. Если Jev медлит или недоступен, маршрутизация оставляет ответ правил.",
  "Decision model provider": "Провайдер модели решений",
  "Jev answers once a key is saved. Create one at {a}. It stays in this machine's secret store and is only sent to {label}.":
    "Jev отвечает, когда ключ сохранён. Создайте его на {a}. Он хранится в хранилище секретов этой машины и отправляется только в {label}.",
