    "Подключитесь к окружению, чтобы очистить данные профиля",
  "Remove “{name}”?": "Удалить «{name}»?",
  "Its cookies and logins are deleted. Desktop tabs already open in this profile stay open until you close them; server browser tabs close now.":
    "Его cookie и входы будут удалены. Уже открытые в этом профиле вкладки на компьютере останутся открытыми, пока вы их не закроете; вкладки серверного браузера закроются сразу.",
