  "Opens setup on this machine. It does not start an agent.":
    "Открывает настройку на этой машине. Агента не запускает.",
  "Add a project": "Добавить проект",
  Online: "В сети",
  "Close terminal": "Закрыть терминал",
  "This connection cannot control terminals on this machine.":
    "Это подключение не может управлять терминалами на этой машине.",
  Close: "Закрыть",
  "Allow again": "Разрешить снова",
  "Allowed before work could be limited, so it may use every project and sign-in here until you change it.":
    "Разрешено до того, как работу можно было ограничивать, поэтому она может использовать все проекты и входы здесь, пока вы это не измените.",
  "Whose machine": "Чья машина",
