  "Adding a Linux server you rent? Start with the {a}.":
    "Добавляете арендованный Linux-сервер? Начните с {a}.",
  "Linux worker guide": "руководства по Linux-воркеру",
  "Link SpecWithCode Connect here first, then make a line to paste on your main machine.":
    "Сначала подключите здесь SpecWithCode Connect, затем создайте строку для вставки на основной машине.",
  "Make a join line": "Создать строку подключения",
  "Turn Auto off": "Выключить Auto",
  "Long audio is transcribed first (speech to text), the transcript is split into chunks that fit the model's context, and the cheaper model works through the chunks. Auto never sends audio to a model that cannot hear it.":
    "Длинное аудио сначала расшифровывается (речь в текст), расшифровка делится на части, помещающиеся в контекст модели, и более дешёвая модель обрабатывает их по очереди. Auto никогда не отправляет аудио модели, которая не умеет его слушать.",
  "A failure on the cheaper model gets one retry on the model the work would have used without Auto. Model changes happen only between turns.":
    "Сбой на более дешёвой модели получает одну повторную попытку на модели, которая использовалась бы без Auto. Модель меняется только между ходами.",
  "Routing conflicts": "Конфликты маршрутизации",
  "task tiers": "уровни задач",
  "Default ({value})": "По умолчанию ({value})",
  "Let Auto use paid API models?": "Разрешить Auto платные API-модели?",
  "Workers in this project may run on providers billed per token, up to the tier you picked. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "Воркеры этого проекта могут работать на провайдерах с потокенной оплатой, вплоть до выбранного уровня. Такие ходы оплачиваются с API-аккаунта провайдера по API-тарифам. SpecWithCode не может видеть или ограничивать этот баланс; задайте лимит расходов у провайдера.",
  "Workers may run on providers billed per token, up to the tier you picked, in every project that does not override this. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "Воркеры могут работать на провайдерах с потокенной оплатой, вплоть до выбранного уровня, во всех проектах, где это не переопределено. Такие ходы оплачиваются с API-аккаунта провайдера по API-тарифам. SpecWithCode не может видеть или ограничивать этот баланс; задайте лимит расходов у провайдера.",
  "Allow paid API": "Разрешить платный API",
